import "@mui/material/FormControl";
export const ThemedFormControl = {
    styleOverrides: {
        root: () => ({
            // If the parent `FormGroup` contains outlined FormControlLabels, apply 8px margins
            // Wrapped in @supports to prevent jsdom test failures (jsdom doesn't support :has())
            "@supports selector(:has(*))": {
                "&:has(.MuiFormControlLabel-root[variant='outlined'])": {
                    "& .MuiFormHelperText-root": {
                        marginTop: "8px",
                    },
                    "& .MuiFormLabel-root": {
                        marginBottom: "8px",
                    },
                },
            },
        }),
    },
};
